input.command:
firecrawl interact -s 01a15575-f4f7-747b-a9f0-f207b101bcb3 --node --timeout 280 -c '
const out=[];
for (const dz of ["10001","60601","33101","98101","96813"]) for (const p of [2,6]) {
  await page.goto(`https://postcalc.usps.com/Calculator/LargePackageProperties?country=0&ccode=US&oz=94107&omil=False&dz=${dz}&dmil=False&retail=False&mdt=10%2F19%2F2026&mdz=14%3A59&m=7&hscode=False&p=${p}&o=0`);
  await page.fill("#Length","12"); await page.fill("#Width","9"); await page.fill("#Height","4");
  await page.click("input[type=submit]");
  await page.waitForLoadState("networkidle");
  const t = await page.innerText("body");
  const s = t.indexOf("Large Package, weight"); 
  const sec = t.slice(s, t.indexOf("Priority Mail Express Items"));
  out.push("=== "+dz+" "+p+"lb\n"+sec.split("\n").filter(l=>/Large Package,|from |^Priority Mail®$|^USPS Ground|Normal Delivery/.test(l)).join("\n"));
}
console.log(out.join("\n"));' 2>&1 | tail -120

